import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CdvW4CUT.js";const f=JSON.parse('{"title":"Kernel 日报 2026-11-26","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/26.md","filePath":"notes/kernel-digest/2026/11/26.md"}'),n={name:"notes/kernel-digest/2026/11/26.md"};function l(c,e,s,d,i,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-26" tabindex="-1">Kernel 日报 2026-11-26 <a class="header-anchor" href="#kernel-日报-2026-11-26" aria-label="Permalink to &quot;Kernel 日报 2026-11-26&quot;">​</a></h1><blockquote><p>生成时间：2026-11-26T01:48:42Z｜共 53 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-26 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_4db90b673261-·-patch-net-next-v2-00-13-ipv6-validate-cached-dsts-against-the-netns-route-generation" tabindex="-1"><code>4db90b673261</code> · <a href="https://lore.kernel.org/all/cover.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 00/13] ipv6: validate cached dsts against the netns route generation</a> <a class="header-anchor" href="#_4db90b673261-·-patch-net-next-v2-00-13-ipv6-validate-cached-dsts-against-the-netns-route-generation" aria-label="Permalink to &quot;`4db90b673261` · [[PATCH net-next v2 00/13] ipv6: validate cached dsts against the netns route generation](https://lore.kernel.org/all/cover.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev｜网络</em></p><p>本系列总览：IPv6 dst 通过 cookie 验证，cookie 由持有者（socket、dst_cache、xfrm bundle、IPVS 等）在存储 dst 时从路由节点的 fn_sernum 捕获，但查找与捕获之间落地的路由变更会被折叠进 cookie，使过期 dst 看似有效。只有 nexthop object 的 pcpu 路由携带自己的 generation，且失效的 pcpu dst 可被重新盖章而再次对所有持有者有效。结果是 dst 持续绕过路由变更，本系列以 netns 路由 generation 统一验证所有 dst。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，清晰梳理了 IPv6 dst 验证机制的历史缺陷与整体修复思路，是理解整个补丁系列的必读入口。</p></blockquote><h3 id="_96e5a91f59fa-·-patch-net-v7-0-3-tls-fix-device-down-socket-lifetime-and-offload-state" tabindex="-1"><code>96e5a91f59fa</code> · <a href="https://lore.kernel.org/all/20261126014327.1638133-1-rjethwani@purestorage.com/" target="_blank" rel="noreferrer">[PATCH net v7 0/3] tls: fix device-down socket lifetime and offload state</a> <a class="header-anchor" href="#_96e5a91f59fa-·-patch-net-v7-0-3-tls-fix-device-down-socket-lifetime-and-offload-state" aria-label="Permalink to &quot;`96e5a91f59fa` · [[PATCH net v7 0/3] tls: fix device-down socket lifetime and offload state](https://lore.kernel.org/all/20261126014327.1638133-1-rjethwani@purestorage.com/)&quot;">​</a></h3><p><em>Rishikesh Jethwani (<a href="mailto:rjethwani@purestorage.com" target="_blank" rel="noreferrer">rjethwani@purestorage.com</a>)｜netdev｜网络</em></p><p>本系列修复 tls_device_down() 中的 socket use-after-free 和错误的 TX/RX 驱动状态处理：补丁 1 在持有 tls_device_lock 时设置 sk_validate_xmit_skb，补丁 2 仅对硬件 TX socket 安装 tls_validate_xmit_skb_sw()。同时 setup 在释放 device_offload_lock 前发布 sk_validate_xmit_skb()，TLS_TX_DEV_DOWN 记录 TX tls_dev_del() 的替换而不依赖 tx_conf。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，清晰梳理了 kTLS 设备卸载下线路径的竞态与状态机问题，适合整体理解该子系统。</p></blockquote><h3 id="_3ceff5b43fc1-·-patch-rfc-00-19-riscv-add-initial-support-for-espressif-esp32-p4" tabindex="-1"><code>3ceff5b43fc1</code> · <a href="https://lore.kernel.org/all/20261125233020.1380594-1-vitorhg20080@gmail.com/" target="_blank" rel="noreferrer">[PATCH RFC 00/19] riscv: Add initial support for Espressif ESP32-P4</a> <a class="header-anchor" href="#_3ceff5b43fc1-·-patch-rfc-00-19-riscv-add-initial-support-for-espressif-esp32-p4" aria-label="Permalink to &quot;`3ceff5b43fc1` · [[PATCH RFC 00/19] riscv: Add initial support for Espressif ESP32-P4](https://lore.kernel.org/all/20261125233020.1380594-1-vitorhg20080@gmail.com/)&quot;">​</a></h3><p><em>Vítor Hugo Silva (<a href="mailto:vitorhg20080@gmail.com" target="_blank" rel="noreferrer">vitorhg20080@gmail.com</a>)｜linux-mm｜内存管理</em></p><p>该系列补丁（19 个）为 Espressif ESP32-P4（Waveshare 开发板）添加初始内核支持，可在 RV32 NOMMU 内核上以 M-mode 单 HP hart 启动。内容包括 CLIC trap 处理、clic 与中断矩阵驱动、扩展 CLINT timer 驱动、恢复 ESP32 UART 驱动并支持 ESP32-P4 与早期控制台、PSRAM 指令同步、按 PMP 粒度对齐 init 数据，以及 DT bindings 和板级 devicetree。</p><blockquote><p><strong>学习价值</strong>：完整的 SoC 移植系列，覆盖中断、定时器、UART、缓存同步和设备树等子系统，是学习 bring-up 流程的好材料。</p></blockquote><h3 id="aa7012012002-·-patch-21-21-rfc-mm-hugetlb-cgroup-charge-faults-to-mm-owner" tabindex="-1"><code>aa7012012002</code> · <a href="https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-21-db27fd2f71a8@kernel.org/" target="_blank" rel="noreferrer">[PATCH 21/21] RFC: mm/hugetlb_cgroup: charge faults to mm-&gt;owner</a> <a class="header-anchor" href="#aa7012012002-·-patch-21-21-rfc-mm-hugetlb-cgroup-charge-faults-to-mm-owner" aria-label="Permalink to &quot;`aa7012012002` · [[PATCH 21/21] RFC: mm/hugetlb_cgroup: charge faults to mm-&gt;owner](https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-21-db27fd2f71a8@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm｜内存管理</em></p><p>该 RFC 补丁修复 hugetlb cgroup 限额绕过问题：__hugetlb_cgroup_charge_cgroup() 向 current 的 hugetlb cgroup 计费，而内核线程通常位于无限额的 root cgroup。例如 KVM 的 async page fault 在 kworker 中重试 vCPU 刚因限额失败的缺页时，会错误地向 root cgroup 计费。补丁改为向 mm-&gt;owner 计费。</p><blockquote><p><strong>学习价值</strong>：揭示了 cgroup 计费中 current 与实际内存使用者不一致的经典陷阱，对理解 KVM async PF 与 hugetlb 计费机制很有价值。</p></blockquote><h3 id="_9e7f1c2fcb60-·-tainting-or-not-on-manual-driver-binding" tabindex="-1"><code>9e7f1c2fcb60</code> · <a href="https://lwn.net/Articles/1103714/" target="_blank" rel="noreferrer">[$] Tainting (or not) on manual driver binding</a> <a class="header-anchor" href="#_9e7f1c2fcb60-·-tainting-or-not-on-manual-driver-binding" aria-label="Permalink to &quot;`9e7f1c2fcb60` · [[$] Tainting (or not) on manual driver binding](https://lwn.net/Articles/1103714/)&quot;">​</a></h3><p><em>corbet｜lwn｜<strong>LWN 订阅文章，仅预览</strong>｜其他动态</em></p><p>Greg Kroah-Hartman 在 7.4 merge window 中合入了一个补丁，当用户空间手动 bind/unbind 设备驱动时将内核标记为 tainted，以抵御 fuzzer 产生的大量虚假 bug 报告。但该改动也阻碍了一些真实使用场景，经讨论后被 revert。这暴露了内核在驱动绑定接口设计上的不足。</p><blockquote><p><strong>学习价值</strong>：展示了内核 taint 机制的实际用途与副作用，以及社区如何权衡 fuzzing 噪音与合法用例，是理解内核开发流程的好案例。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（7 条）</li><li><strong>网络</strong>（18 条）</li><li><strong>文件系统与存储</strong>（3 条）</li><li><strong>Rust in Linux</strong>（15 条）</li><li><strong>跟踪与性能</strong>（1 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（8 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="d95d6be51e13-·-patch-v2-risc-v-kvm-account-g-stage-page-table-memory" tabindex="-1"><code>d95d6be51e13</code> · <a href="https://lore.kernel.org/all/20261126013724.2533363-1-tanchi25@mails.ucas.ac.cn/" target="_blank" rel="noreferrer">[PATCH v2] RISC-V: KVM: Account G-stage page table memory</a> <a class="header-anchor" href="#d95d6be51e13-·-patch-v2-risc-v-kvm-account-g-stage-page-table-memory" aria-label="Permalink to &quot;`d95d6be51e13` · [[PATCH v2] RISC-V: KVM: Account G-stage page table memory](https://lore.kernel.org/all/20261126013724.2533363-1-tanchi25@mails.ucas.ac.cn/)&quot;">​</a></h3><p><em>Tan Chi (<a href="mailto:tanchi25@mails.ucas.ac.cn" target="_blank" rel="noreferrer">tanchi25@mails.ucas.ac.cn</a>)｜lkml</em></p><p>该补丁为 RISC-V KVM 补上 G-stage 页表内存的统计：使用 kvm_account_pgtable_pages() 对根级及下层页表（包括拆分 huge page 时分配的页表）的分配与释放进行记账，使其可通过 /proc/meminfo 的 SecPageTables 和 cgroup memory.stat 的 sec_pagetables 观测。在 QEMU TCG + Sv57x4 环境下测试，100 个空 VM 占用约 1600 KiB G-stage 页表内存。</p><blockquote><p><strong>学习价值</strong>：展示了 KVM 二级地址转换（G-stage）页表内存记账的实现方式，是学习虚拟化内存管理与 memcg 统计接口的优秀实例。</p></blockquote><h3 id="e87113121a3b-·-patch-selftests-cachestat-clean-up-the-mmap-test-scratch-file" tabindex="-1"><code>e87113121a3b</code> · <a href="https://lore.kernel.org/all/20261126011818.417-1-tongzhiwei@cmss.chinamobile.com/" target="_blank" rel="noreferrer">[PATCH] selftests/cachestat: clean up the mmap test scratch file</a> <a class="header-anchor" href="#e87113121a3b-·-patch-selftests-cachestat-clean-up-the-mmap-test-scratch-file" aria-label="Permalink to &quot;`e87113121a3b` · [[PATCH] selftests/cachestat: clean up the mmap test scratch file](https://lore.kernel.org/all/20261126011818.417-1-tongzhiwei@cmss.chinamobile.com/)&quot;">​</a></h3><p><em>tongzhiwei (<a href="mailto:tongzhiwei@cmss.chinamobile.com" target="_blank" rel="noreferrer">tongzhiwei@cmss.chinamobile.com</a>)｜linux-mm</em></p><p>修复 selftests/cachestat 中的清理逻辑错误：run_cachestat_test() 用 open() 创建 FILE_MMAP 临时文件，却用 shm_unlink() 清理，而后者只能删除 /dev/shm 下的 POSIX 共享内存对象，导致普通文件 tmpshmcstat 每次运行后残留在工作目录。补丁改为正确的清理方式，同时保留 .gitignore 条目作为中断情况的安全网。</p><blockquote><p><strong>学习价值</strong>：提醒学习者注意 POSIX shm 与普通文件 API 的区别，以及自测试代码的资源清理规范；该修复由 LLM 发现但经人工审查。</p></blockquote><h3 id="_52fc235a9aeb-·-patch-rfc-14-19-riscv-synchronize-instructions-written-to-esp32-p4-psram" tabindex="-1"><code>52fc235a9aeb</code> · <a href="https://lore.kernel.org/all/20261125233020.1380594-15-vitorhg20080@gmail.com/" target="_blank" rel="noreferrer">[PATCH RFC 14/19] riscv: Synchronize instructions written to ESP32-P4 PSRAM</a> <a class="header-anchor" href="#_52fc235a9aeb-·-patch-rfc-14-19-riscv-synchronize-instructions-written-to-esp32-p4-psram" aria-label="Permalink to &quot;`52fc235a9aeb` · [[PATCH RFC 14/19] riscv: Synchronize instructions written to ESP32-P4 PSRAM](https://lore.kernel.org/all/20261125233020.1380594-15-vitorhg20080@gmail.com/)&quot;">​</a></h3><p><em>Vítor Hugo Silva (<a href="mailto:vitorhg20080@gmail.com" target="_blank" rel="noreferrer">vitorhg20080@gmail.com</a>)｜linux-mm</em></p><p>在 ESP32-P4 上，load 可能通过数据缓存观察到新写入 PSRAM 的指令字节，而取指路径仍看到旧字节，导致运行时常量 patching 在启动时执行过期指令。补丁对被修改的 PSRAM 范围回写 L1 数据缓存和 L2 缓存、失效本地 L1 指令缓存并执行 fence.i，同样的序列也应用于 NOMMU 用户态代码（包括 FLAT 二进制和信号返回 trampoline），并将对齐范围切分为 32 KiB 块处理。</p><blockquote><p><strong>学习价值</strong>：深入展示了非一致性 I/D 缓存架构下的指令同步问题，是理解 RISC-V fence.i 与缓存维护的难得实例。</p></blockquote><h3 id="_3ceff5b43fc1-·-patch-rfc-00-19-riscv-add-initial-support-for-espressif-esp32-p4-1" tabindex="-1"><code>3ceff5b43fc1</code> · <a href="https://lore.kernel.org/all/20261125233020.1380594-1-vitorhg20080@gmail.com/" target="_blank" rel="noreferrer">[PATCH RFC 00/19] riscv: Add initial support for Espressif ESP32-P4</a> <a class="header-anchor" href="#_3ceff5b43fc1-·-patch-rfc-00-19-riscv-add-initial-support-for-espressif-esp32-p4-1" aria-label="Permalink to &quot;`3ceff5b43fc1` · [[PATCH RFC 00/19] riscv: Add initial support for Espressif ESP32-P4](https://lore.kernel.org/all/20261125233020.1380594-1-vitorhg20080@gmail.com/)&quot;">​</a></h3><p><em>Vítor Hugo Silva (<a href="mailto:vitorhg20080@gmail.com" target="_blank" rel="noreferrer">vitorhg20080@gmail.com</a>)｜linux-mm</em></p><p>该系列补丁（19 个）为 Espressif ESP32-P4（Waveshare 开发板）添加初始内核支持，可在 RV32 NOMMU 内核上以 M-mode 单 HP hart 启动。内容包括 CLIC trap 处理、clic 与中断矩阵驱动、扩展 CLINT timer 驱动、恢复 ESP32 UART 驱动并支持 ESP32-P4 与早期控制台、PSRAM 指令同步、按 PMP 粒度对齐 init 数据，以及 DT bindings 和板级 devicetree。</p><blockquote><p><strong>学习价值</strong>：完整的 SoC 移植系列，覆盖中断、定时器、UART、缓存同步和设备树等子系统，是学习 bring-up 流程的好材料。</p></blockquote><h3 id="aa7012012002-·-patch-21-21-rfc-mm-hugetlb-cgroup-charge-faults-to-mm-owner-1" tabindex="-1"><code>aa7012012002</code> · <a href="https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-21-db27fd2f71a8@kernel.org/" target="_blank" rel="noreferrer">[PATCH 21/21] RFC: mm/hugetlb_cgroup: charge faults to mm-&gt;owner</a> <a class="header-anchor" href="#aa7012012002-·-patch-21-21-rfc-mm-hugetlb-cgroup-charge-faults-to-mm-owner-1" aria-label="Permalink to &quot;`aa7012012002` · [[PATCH 21/21] RFC: mm/hugetlb_cgroup: charge faults to mm-&gt;owner](https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-21-db27fd2f71a8@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>该 RFC 补丁修复 hugetlb cgroup 限额绕过问题：__hugetlb_cgroup_charge_cgroup() 向 current 的 hugetlb cgroup 计费，而内核线程通常位于无限额的 root cgroup。例如 KVM 的 async page fault 在 kworker 中重试 vCPU 刚因限额失败的缺页时，会错误地向 root cgroup 计费。补丁改为向 mm-&gt;owner 计费。</p><blockquote><p><strong>学习价值</strong>：揭示了 cgroup 计费中 current 与实际内存使用者不一致的经典陷阱，对理解 KVM async PF 与 hugetlb 计费机制很有价值。</p></blockquote><h3 id="fe17f5c508c1-·-patch-20-21-mm-hugetlb-resolve-protnone-faults-without-a-uffd-bit" tabindex="-1"><code>fe17f5c508c1</code> · <a href="https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-20-db27fd2f71a8@kernel.org/" target="_blank" rel="noreferrer">[PATCH 20/21] mm/hugetlb: resolve protnone faults without a uffd bit</a> <a class="header-anchor" href="#fe17f5c508c1-·-patch-20-21-mm-hugetlb-resolve-protnone-faults-without-a-uffd-bit" aria-label="Permalink to &quot;`fe17f5c508c1` · [[PATCH 20/21] mm/hugetlb: resolve protnone faults without a uffd bit](https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-20-db27fd2f71a8@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>hugetlb_fault() 目前只恢复设置了 uffd 位的 protnone 页表项的保护属性，假设可访问 VMA 中不存在其他 protnone 项；若存在则会导致无限缺页循环。虽然目前未发现可触发的路径，补丁采取防御性策略，使任何 protnone 项都能被正确处理而无需 uffd 位。</p><blockquote><p><strong>学习价值</strong>：体现了内核开发中“防御性修复潜在死循环”的思路，适合学习 hugetlb 缺页处理与 userfaultfd 的交互。</p></blockquote><h3 id="_855b21f48ec2-·-patch-19-21-mm-hugetlb-use-the-vma-lock-to-stabilize-flags-for-pmd-sharing" tabindex="-1"><code>855b21f48ec2</code> · <a href="https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-19-db27fd2f71a8@kernel.org/" target="_blank" rel="noreferrer">[PATCH 19/21] mm/hugetlb: use the VMA lock to stabilize flags for PMD sharing</a> <a class="header-anchor" href="#_855b21f48ec2-·-patch-19-21-mm-hugetlb-use-the-vma-lock-to-stabilize-flags-for-pmd-sharing" aria-label="Permalink to &quot;`855b21f48ec2` · [[PATCH 19/21] mm/hugetlb: use the VMA lock to stabilize flags for PMD sharing](https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-19-db27fd2f71a8@kernel.org/)&quot;">​</a></h3><p><em>David Hildenbrand (Arm) (<a href="mailto:david@kernel.org" target="_blank" rel="noreferrer">david@kernel.org</a>)｜linux-mm</em></p><p>huge_pmd_share() 目前只有在能读锁对方 mm 的 mmap lock 时才共享页表，这在 mm 被写锁或锁竞争时会拒绝共享。补丁改为只读锁对应的 VMA lock：由于持有 i_mmap_rwsem，该 VMA 不会消失。同时新增 vma_trylock_read() 变体，不要求在 RCU 读锁下调用也不会自行释放锁。</p><blockquote><p><strong>学习价值</strong>：展示了 per-VMA lock 替代 mmap lock 降低锁粒度的优化趋势，是学习现代 VMA 锁机制的好例子。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_0ed901ba43f6-·-patch-net-v7-3-3-tls-use-tls-rx-dev-closed-to-skip-rx-tls-dev-del-in-device-down" tabindex="-1"><code>0ed901ba43f6</code> · <a href="https://lore.kernel.org/all/20261126014327.1638133-4-rjethwani@purestorage.com/" target="_blank" rel="noreferrer">[PATCH net v7 3/3] tls: use TLS_RX_DEV_CLOSED to skip RX tls_dev_del in device-down</a> <a class="header-anchor" href="#_0ed901ba43f6-·-patch-net-v7-3-3-tls-use-tls-rx-dev-closed-to-skip-rx-tls-dev-del-in-device-down" aria-label="Permalink to &quot;`0ed901ba43f6` · [[PATCH net v7 3/3] tls: use TLS_RX_DEV_CLOSED to skip RX tls_dev_del in device-down](https://lore.kernel.org/all/20261126014327.1638133-4-rjethwani@purestorage.com/)&quot;">​</a></h3><p><em>Rishikesh Jethwani (<a href="mailto:rjethwani@purestorage.com" target="_blank" rel="noreferrer">rjethwani@purestorage.com</a>)｜netdev</em></p><p>修复 kTLS 设备卸载的竞态：do_tls_setsockopt_conf() 在 tls_set_device_offload_rx() 释放 device_offload_lock 之后才设置 rx_conf，导致 tls_device_down() 可能看到 RX tls_dev_add() 已成功但 rx_conf 尚未置为 TLS_HW 的上下文，从而跳过 RX tls_dev_del 并泄漏驱动状态。补丁扩展 TLS_RX_DEV_CLOSED 标志的含义以覆盖此类状态，且 rx_conf 与 tx_conf 共享字节存在无锁写问题。</p><blockquote><p><strong>学习价值</strong>：典型的锁释放与状态标志设置顺序不当引发的竞态案例，适合学习 kTLS 设备卸载路径的同步设计。</p></blockquote><h3 id="af88b9e65cc6-·-patch-net-v7-2-3-tls-restrict-device-down-tx-fallback-to-hardware-tx-sockets" tabindex="-1"><code>af88b9e65cc6</code> · <a href="https://lore.kernel.org/all/20261126014327.1638133-3-rjethwani@purestorage.com/" target="_blank" rel="noreferrer">[PATCH net v7 2/3] tls: restrict device-down TX fallback to hardware TX sockets</a> <a class="header-anchor" href="#af88b9e65cc6-·-patch-net-v7-2-3-tls-restrict-device-down-tx-fallback-to-hardware-tx-sockets" aria-label="Permalink to &quot;`af88b9e65cc6` · [[PATCH net v7 2/3] tls: restrict device-down TX fallback to hardware TX sockets](https://lore.kernel.org/all/20261126014327.1638133-3-rjethwani@purestorage.com/)&quot;">​</a></h3><p><em>Rishikesh Jethwani (<a href="mailto:rjethwani@purestorage.com" target="_blank" rel="noreferrer">rjethwani@purestorage.com</a>)｜netdev</em></p><p>tls_device_down() 会对设备上所有 offloaded TLS socket 设置 sk_validate_xmit_skb 为 tls_validate_xmit_skb_sw()，包括仅 RX offload 或软件 TX 的 socket。tls_validate_xmit_skb_sw() 会将 skb 传给 tls_sw_fallback()，后者期望 priv_ctx_tx 中存在 tls_offload_context_tx，导致此类 socket 在发送 payload skb 时触发 NULL pointer dereference 崩溃。补丁将 TX fallback 限制到硬件 TX socket。</p><blockquote><p><strong>学习价值</strong>：展示了 kTLS offload 路径中 TX/RX 上下文不对称导致的空指针崩溃，是理解 kTLS 硬件卸载架构的好案例。</p></blockquote><h3 id="edc859d820ef-·-patch-net-v7-1-3-tls-fix-socket-use-after-free-during-device-down" tabindex="-1"><code>edc859d820ef</code> · <a href="https://lore.kernel.org/all/20261126014327.1638133-2-rjethwani@purestorage.com/" target="_blank" rel="noreferrer">[PATCH net v7 1/3] tls: fix socket use-after-free during device-down</a> <a class="header-anchor" href="#edc859d820ef-·-patch-net-v7-1-3-tls-fix-socket-use-after-free-during-device-down" aria-label="Permalink to &quot;`edc859d820ef` · [[PATCH net v7 1/3] tls: fix socket use-after-free during device-down](https://lore.kernel.org/all/20261126014327.1638133-2-rjethwani@purestorage.com/)&quot;">​</a></h3><p><em>Rishikesh Jethwani (<a href="mailto:rjethwani@purestorage.com" target="_blank" rel="noreferrer">rjethwani@purestorage.com</a>)｜netdev</em></p><p>tls_device_down() 在持有 TLS context 引用后、设置 sk_validate_xmit_skb 之前释放了 tls_device_lock，此时 socket 可能被释放：tls_device_sk_destruct() 通过 tls_device_queue_ctx_destruction() 丢弃 context 引用，随后 __sk_destruct() 释放 socket，造成 use-after-free。修复方案是在遍历 tls_device_list 时持有 tls_device_lock 的情况下设置 sk_validate_xmit_skb。</p><blockquote><p><strong>学习价值</strong>：典型的锁保护窗口内引用生命周期错误，对学习内核并发与引用计数设计非常有价值。</p></blockquote><h3 id="_96e5a91f59fa-·-patch-net-v7-0-3-tls-fix-device-down-socket-lifetime-and-offload-state-1" tabindex="-1"><code>96e5a91f59fa</code> · <a href="https://lore.kernel.org/all/20261126014327.1638133-1-rjethwani@purestorage.com/" target="_blank" rel="noreferrer">[PATCH net v7 0/3] tls: fix device-down socket lifetime and offload state</a> <a class="header-anchor" href="#_96e5a91f59fa-·-patch-net-v7-0-3-tls-fix-device-down-socket-lifetime-and-offload-state-1" aria-label="Permalink to &quot;`96e5a91f59fa` · [[PATCH net v7 0/3] tls: fix device-down socket lifetime and offload state](https://lore.kernel.org/all/20261126014327.1638133-1-rjethwani@purestorage.com/)&quot;">​</a></h3><p><em>Rishikesh Jethwani (<a href="mailto:rjethwani@purestorage.com" target="_blank" rel="noreferrer">rjethwani@purestorage.com</a>)｜netdev</em></p><p>本系列修复 tls_device_down() 中的 socket use-after-free 和错误的 TX/RX 驱动状态处理：补丁 1 在持有 tls_device_lock 时设置 sk_validate_xmit_skb，补丁 2 仅对硬件 TX socket 安装 tls_validate_xmit_skb_sw()。同时 setup 在释放 device_offload_lock 前发布 sk_validate_xmit_skb()，TLS_TX_DEV_DOWN 记录 TX tls_dev_del() 的替换而不依赖 tx_conf。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，清晰梳理了 kTLS 设备卸载下线路径的竞态与状态机问题，适合整体理解该子系统。</p></blockquote><h3 id="_990f65977820-·-patch-net-next-v2-13-13-selftests-net-ipvs-check-a-pmtu-learned-after-the-dr-route-was-cached" tabindex="-1"><code>990f65977820</code> · <a href="https://lore.kernel.org/all/54d8eada69c6793d4761274f9c2878c0d284fe8b.1795642478.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 13/13] selftests: net: ipvs: check a PMTU learned after the DR route was cached</a> <a class="header-anchor" href="#_990f65977820-·-patch-net-next-v2-13-13-selftests-net-ipvs-check-a-pmtu-learned-after-the-dr-route-was-cached" aria-label="Permalink to &quot;`990f65977820` · [[PATCH net-next v2 13/13] selftests: net: ipvs: check a PMTU learned after the DR route was cached](https://lore.kernel.org/all/54d8eada69c6793d4761274f9c2878c0d284fe8b.1795642478.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>该自测针对 IPv6 DR 模式下 IPVS：director 将到 real server 的路由缓存在 dest-&gt;dst_cache 并通过 ip6_dst_check() 重新验证，但该路由是 FLOWI_FLAG_KNOWN_NH 克隆、不在 nexthop 上缓存，因此后续学到的 PMTU 不会应用到它。测试先缓存路由，再通过伪造的 packet too big 消息给 director 设置 PMTU，验证 director 会以 packet too big 回应超限报文。</p><blockquote><p><strong>学习价值</strong>：演示了如何用 selftests 覆盖 PMTU 与缓存路由交互的边界场景，是学习网络自测编写方法的实用参考。</p></blockquote><h3 id="e256c5fee4ca-·-patch-net-next-v2-12-13-selftests-net-fib-tests-add-stale-pcpu-test" tabindex="-1"><code>e256c5fee4ca</code> · <a href="https://lore.kernel.org/all/44f185f53dfff14a9395f2bb78bbfa9c2a164279.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 12/13] selftests: net: fib_tests: Add stale pcpu test</a> <a class="header-anchor" href="#e256c5fee4ca-·-patch-net-next-v2-12-13-selftests-net-fib-tests-add-stale-pcpu-test" aria-label="Permalink to &quot;`e256c5fee4ca` · [[PATCH net-next v2 12/13] selftests: net: fib_tests: Add stale pcpu test](https://lore.kernel.org/all/44f185f53dfff14a9395f2bb78bbfa9c2a164279.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>为 fib_tests.sh 添加 stale pcpu 路由条目的回归测试，覆盖 commit 8f34e53b60b3（&quot;ipv6: Use global sernum for dst validation with nexthop objects&quot;）所修复的问题，防止回归。</p><blockquote><p><strong>学习价值</strong>：展示了为具体修复 commit 编写回归自测的标准做法，有助于理解 IPv6 dst 验证机制。</p></blockquote><h3 id="f235f1c1cddd-·-patch-net-next-v2-11-13-selftests-net-pmtu-check-that-a-deleted-cached-exception-stays-deleted" tabindex="-1"><code>f235f1c1cddd</code> · <a href="https://lore.kernel.org/all/c1700ffd419c7247da4c896cb09f384894c32f43.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 11/13] selftests: net: pmtu: check that a deleted cached exception stays deleted</a> <a class="header-anchor" href="#f235f1c1cddd-·-patch-net-next-v2-11-13-selftests-net-pmtu-check-that-a-deleted-cached-exception-stays-deleted" aria-label="Permalink to &quot;`f235f1c1cddd` · [[PATCH net-next v2 11/13] selftests: net: pmtu: check that a deleted cached exception stays deleted](https://lore.kernel.org/all/c1700ffd419c7247da4c896cb09f384894c32f43.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>新增 PMTU 自测：先通过 packet too big 消息学习 PMTU，然后修改 FIB 中与目的无关的路由，并在不进行目的查找的情况下删除缓存的 exception。测试验证删除 stale exception 必须生效，且后续的路由查找或报文发送都不会重新创建该 exception。</p><blockquote><p><strong>学习价值</strong>：深入揭示了 PMTU exception 缓存与 FIB 变更之间的失效语义，对理解 IPv6 dst 生命周期很有帮助。</p></blockquote><h3 id="_7c1e9ff6efa6-·-patch-net-next-v2-10-13-ipv6-stamp-dsts-with-the-generation-sampled-before-the-fib-lookup" tabindex="-1"><code>7c1e9ff6efa6</code> · <a href="https://lore.kernel.org/all/9dd4252dc06c088f6e62b7c93156058514994df6.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 10/13] ipv6: stamp dsts with the generation sampled before the FIB lookup</a> <a class="header-anchor" href="#_7c1e9ff6efa6-·-patch-net-next-v2-10-13-ipv6-stamp-dsts-with-the-generation-sampled-before-the-fib-lookup" aria-label="Permalink to &quot;`7c1e9ff6efa6` · [[PATCH net-next v2 10/13] ipv6: stamp dsts with the generation sampled before the FIB lookup](https://lore.kernel.org/all/9dd4252dc06c088f6e62b7c93156058514994df6.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>dst 在 ip6_dst_alloc() 中被盖上 netns 路由 generation 戳，但该函数在 FIB 读取之后执行；若路由变更恰好落在查找与分配之间，dst 会基于旧树构建却携带新 generation，导致 ip6_dst_check() 永远接受它并无限绕过新路由。修复方案是在遍历 FIB 前采样 generation，通过 struct fib6_result 携带，并用它为所有由此构建的 dst 盖戳。</p><blockquote><p><strong>学习价值</strong>：精妙的 TOCTOU 类问题：generation 戳采样时机错误导致缓存失效机制失效，是学习 RCU 与缓存一致性设计的优秀案例。</p></blockquote><h3 id="eb60b6976860-·-patch-net-next-v2-09-13-nexthop-bump-the-ipv6-route-generation-on-group-changes" tabindex="-1"><code>eb60b6976860</code> · <a href="https://lore.kernel.org/all/09d703171e31f488d7015349516203e8196ba843.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 09/13] nexthop: bump the IPv6 route generation on group changes</a> <a class="header-anchor" href="#eb60b6976860-·-patch-net-next-v2-09-13-nexthop-bump-the-ipv6-route-generation-on-group-changes" aria-label="Permalink to &quot;`eb60b6976860` · [[PATCH net-next v2 09/13] nexthop: bump the IPv6 route generation on group changes](https://lore.kernel.org/all/09d703171e31f488d7015349516203e8196ba843.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>IPv6 dst 通过递增 netns 路由 generation 来失效，但两处 nexthop 对象变更未做到：替换作为 group 成员的 nexthop 时仅在成员自身有 IPv6 路由时才递增，未覆盖路由使用包含它的 group 的情况；从 group 移除成员时重新发布 group 数组却完全不递增，导致旧 group 构建的 dst 仍然有效。补丁在这两种情况下，只要 IPv6 路由直接或通过 group 使用该 nexthop 就递增 generation。</p><blockquote><p><strong>学习价值</strong>：展示了 nexthop group 与 IPv6 路由 generation 失效联动中的遗漏场景，有助于理解 nexthop 对象模型的传播机制。</p></blockquote><h3 id="_0b23c711cd00-·-patch-net-next-v2-08-13-nexthop-factor-out-nh-has-f6i" tabindex="-1"><code>0b23c711cd00</code> · <a href="https://lore.kernel.org/all/445f336e64d9d09682c9c9d5cd01d2e6ac290004.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 08/13] nexthop: factor out nh_has_f6i()</a> <a class="header-anchor" href="#_0b23c711cd00-·-patch-net-next-v2-08-13-nexthop-factor-out-nh-has-f6i" aria-label="Permalink to &quot;`0b23c711cd00` · [[PATCH net-next v2 08/13] nexthop: factor out nh_has_f6i()](https://lore.kernel.org/all/445f336e64d9d09682c9c9d5cd01d2e6ac290004.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>将 nh_rt_cache_flush() 中内联的、带锁检查是否有 IPv6 路由使用某 nexthop 的逻辑抽取为 helper 函数 nh_has_f6i()，放置在 remove_nexthop_from_groups() 之前，供下一个补丁复用。无功能变更。</p><blockquote><p><strong>学习价值</strong>：典型的重构准备补丁，体现了内核开发中先抽取 helper 再修复逻辑的渐进式提交风格。</p></blockquote><h3 id="_1e341cc3ceb2-·-patch-net-next-v2-07-13-ipv6-make-rt-genid-bump-ipv6-a-plain-counter-increment" tabindex="-1"><code>1e341cc3ceb2</code> · <a href="https://lore.kernel.org/all/dad848908b05fc8be7dc14d1928d90c676103e14.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 07/13] ipv6: make rt_genid_bump_ipv6() a plain counter increment</a> <a class="header-anchor" href="#_1e341cc3ceb2-·-patch-net-next-v2-07-13-ipv6-make-rt-genid-bump-ipv6-a-plain-counter-increment" aria-label="Permalink to &quot;`1e341cc3ceb2` · [[PATCH net-next v2 07/13] ipv6: make rt_genid_bump_ipv6() a plain counter increment](https://lore.kernel.org/all/dad848908b05fc8be7dc14d1928d90c676103e14.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>rt_genid_bump_ipv6() 原先通过函数指针调用 fib6_flush_trees()，遍历每张表的每个节点写入新的 fn_sernum 以使 cookie 失效；由于缓存 dst 现在直接与 net-&gt;ipv6.fib6_sernum 比对验证，该遍历已无意义。改为像 rt_genid_bump_ipv4() 一样仅递增计数器，保留 fib6_new_sernum() 回绕到 1 的行为，使 nexthop、地址和 FIB 规则变更变得廉价，且不再触碰 route dump 用于检测变化的 fn_sernum。</p><blockquote><p><strong>学习价值</strong>：展示了 dst 验证机制从全表遍历到全局计数器的演进，是理解 IPv6 路由缓存失效成本优化的好材料。</p></blockquote><h3 id="_52a8f7623cce-·-patch-net-next-v2-06-13-ipv6-validate-dsts-against-the-netns-route-generation" tabindex="-1"><code>52a8f7623cce</code> · <a href="https://lore.kernel.org/all/52846eb18319fc2841ffa6dbb32abcc898eca8df.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 06/13] ipv6: validate dsts against the netns route generation</a> <a class="header-anchor" href="#_52a8f7623cce-·-patch-net-next-v2-06-13-ipv6-validate-dsts-against-the-netns-route-generation" aria-label="Permalink to &quot;`52a8f7623cce` · [[PATCH net-next v2 06/13] ipv6: validate dsts against the netns route generation](https://lore.kernel.org/all/52846eb18319fc2841ffa6dbb32abcc898eca8df.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>本补丁修复 IPv6 路由 dst 缓存验证的一个漏洞：rt6_info 从不携带创建时的 fib6 serial number，导致路由查找与 cookie 捕获之间发生的路由变更被折叠进 cookie，使过期 dst 看起来仍然有效。修复方式是在 ip6_dst_alloc() 中为每个 dst 盖上 net-&gt;ipv6.fib6_sernum（即 rt_genid_ipv6() 读取的计数器，每次 FIB 变更都会递增）的戳记，并在验证时进行比较。</p><blockquote><p><strong>学习价值</strong>：展示了 IPv6 路由缓存一致性机制中 generation counter 的经典设计模式，是理解 dst 验证与 FIB 串行号交互的好材料。</p></blockquote><h3 id="_1d7751f35bc4-·-patch-net-next-v2-05-13-ipv6-tell-route-dumps-about-exception-inserts-with-a-table-sequence" tabindex="-1"><code>1d7751f35bc4</code> · <a href="https://lore.kernel.org/all/09874919c6f8c0da76839f5e70bdce66df09b6d6.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 05/13] ipv6: tell route dumps about exception inserts with a table sequence</a> <a class="header-anchor" href="#_1d7751f35bc4-·-patch-net-next-v2-05-13-ipv6-tell-route-dumps-about-exception-inserts-with-a-table-sequence" aria-label="Permalink to &quot;`1d7751f35bc4` · [[PATCH net-next v2 05/13] ipv6: tell route dumps about exception inserts with a table sequence](https://lore.kernel.org/all/09874919c6f8c0da76839f5e70bdce66df09b6d6.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>IPv6 路由 dump 在挂起后恢复时依赖根节点 fn_sernum 变化来从头重启，而 rt6_insert_exception() 调用 fib6_update_sernum() 恰好触发了这一行为，使 dump 一致性与 fn_sernum 的其他语义耦合在一起。本补丁引入每表（per-table）的 tb6_exc 序列号来通知 exception dump 有新插入，解除了这种脆弱的依赖关系，避免本地编造的 sernum 值与 netns 计数器将来发出的值冲突而不被察觉。</p><blockquote><p><strong>学习价值</strong>：揭示了 netlink dump 一致性与 FIB 内部计数器之间的隐蔽耦合，对学习路由 dump 机制和序列号设计很有启发。</p></blockquote><h3 id="d6418f03c05f-·-patch-net-next-v2-04-13-ipv6-invalidate-the-failing-dst-in-ip6-link-failure" tabindex="-1"><code>d6418f03c05f</code> · <a href="https://lore.kernel.org/all/94591642bbaefaea15cf2aa2e0d5ca4e4de74686.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 04/13] ipv6: invalidate the failing dst in ip6_link_failure()</a> <a class="header-anchor" href="#d6418f03c05f-·-patch-net-next-v2-04-13-ipv6-invalidate-the-failing-dst-in-ip6-link-failure" aria-label="Permalink to &quot;`d6418f03c05f` · [[PATCH net-next v2 04/13] ipv6: invalidate the failing dst in ip6_link_failure()](https://lore.kernel.org/all/94591642bbaefaea15cf2aa2e0d5ca4e4de74686.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>当默认路由的邻居失效时，ip6_link_failure() 原本将路由节点 fn_sernum 写为 -1，使该节点下所有 dst 失效并重新选路，这对一个持续发包的失效路由器来说波及面过大。本补丁改为只失效出问题的那个 dst（对 pcpu dst 而言只是单个 CPU 的副本），做法是设置其 sernum 的最高位，使其与 netns 路由 generation 比较时必然不匹配。</p><blockquote><p><strong>学习价值</strong>：演示了如何用 sernum 位操作实现细粒度 dst 失效，是学习 IPv6 路由错误处理与 pcpu 路由机制的实用案例。</p></blockquote><h3 id="ef45ef04d67f-·-patch-net-next-v2-03-13-ipv6-don-t-insert-a-pmtu-exception-whose-mtu-could-not-be-stored" tabindex="-1"><code>ef45ef04d67f</code> · <a href="https://lore.kernel.org/all/e158d506fc9aab4b823c28cc1a3bfcaff0e7f67b.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 03/13] ipv6: don&#39;t insert a PMTU exception whose MTU could not be stored</a> <a class="header-anchor" href="#ef45ef04d67f-·-patch-net-next-v2-03-13-ipv6-don-t-insert-a-pmtu-exception-whose-mtu-could-not-be-stored" aria-label="Permalink to &quot;`ef45ef04d67f` · [[PATCH net-next v2 03/13] ipv6: don&#39;t insert a PMTU exception whose MTU could not be stored](https://lore.kernel.org/all/e158d506fc9aab4b823c28cc1a3bfcaff0e7f67b.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>rt6_do_update_pmtu() 通过 dst_metric_set() 设置 MTU，但该函数在首次使用时用 GFP_ATOMIC 分配可写 metrics，失败时静默返回而不通知调用者。这导致 PMTU 更新插入了一个没有学到 MTU 的 exception，既没有降低任何值，还替换了该目的地已有的 exception 并使 nexthop 的缓存 dst 失效。本补丁确保 MTU 无法存储时不插入 exception。</p><blockquote><p><strong>学习价值</strong>：展示了 GFP_ATOMIC 分配失败在 PMTU exception 路径上的连锁后果，是学习错误传播与 dst metrics 共享机制的典型案例。</p></blockquote><h3 id="_4f7d9366b63f-·-patch-net-next-v2-02-13-ipv6-keep-a-superseded-pcpu-dst-working-until-its-holders-notice" tabindex="-1"><code>4f7d9366b63f</code> · <a href="https://lore.kernel.org/all/9a45f4107473a2ab534f0c17ee237ff5344573bc.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 02/13] ipv6: keep a superseded pcpu dst working until its holders notice</a> <a class="header-anchor" href="#_4f7d9366b63f-·-patch-net-next-v2-02-13-ipv6-keep-a-superseded-pcpu-dst-working-until-its-holders-notice" aria-label="Permalink to &quot;`4f7d9366b63f` · [[PATCH net-next v2 02/13] ipv6: keep a superseded pcpu dst working until its holders notice](https://lore.kernel.org/all/9a45f4107473a2ab534f0c17ee237ff5344573bc.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>当 rt6_get_pcpu_route() 发现使用 nexthop object 的路由的 pcpu dst 已失效时，会将其从槽位取出并调用 dst_dev_put()，使其指向 blackhole 设备并丢弃输出——但此时 dst 可能仍被 socket、tunnel dst_cache、xfrm bundle 或尚未到达 dst_output() 的 skb 持有，导致这些包被无谓丢弃。本补丁让被取代的 pcpu dst 在持有者下次检查并重新选路之前继续可用。</p><blockquote><p><strong>学习价值</strong>：深入剖析了 dst 引用持有者与失效时机的交互，对理解内核缓存对象生命周期管理非常有价值。</p></blockquote><h3 id="_23db2a7b8c58-·-patch-net-next-v2-01-13-ipv6-allocate-the-exception-entry-before-removing-the-one-it-replaces" tabindex="-1"><code>23db2a7b8c58</code> · <a href="https://lore.kernel.org/all/09f2c4510b77554f66cb3c56f8667a2d2864b959.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 01/13] ipv6: allocate the exception entry before removing the one it replaces</a> <a class="header-anchor" href="#_23db2a7b8c58-·-patch-net-next-v2-01-13-ipv6-allocate-the-exception-entry-before-removing-the-one-it-replaces" aria-label="Permalink to &quot;`23db2a7b8c58` · [[PATCH net-next v2 01/13] ipv6: allocate the exception entry before removing the one it replaces](https://lore.kernel.org/all/09f2c4510b77554f66cb3c56f8667a2d2864b959.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>rt6_insert_exception() 原本先解除已有 exception 的链接，再用 GFP_ATOMIC 分配替换条目；若分配失败，已学到的信息（降低的 PMTU 或 redirect 网关）已经丢失，流量只能回退到路由自身的 MTU 和网关。本补丁改为先分配条目，失败时什么都不动，原有 exception 保持不变。修复 35732d01fe31 引入的 dst cache hash table 问题。</p><blockquote><p><strong>学习价值</strong>：一个简洁的&#39;先分配后修改&#39;错误处理模式示例，适合学习内核路径中原子分配失败时的回滚设计。</p></blockquote><h3 id="_4db90b673261-·-patch-net-next-v2-00-13-ipv6-validate-cached-dsts-against-the-netns-route-generation-1" tabindex="-1"><code>4db90b673261</code> · <a href="https://lore.kernel.org/all/cover.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 00/13] ipv6: validate cached dsts against the netns route generation</a> <a class="header-anchor" href="#_4db90b673261-·-patch-net-next-v2-00-13-ipv6-validate-cached-dsts-against-the-netns-route-generation-1" aria-label="Permalink to &quot;`4db90b673261` · [[PATCH net-next v2 00/13] ipv6: validate cached dsts against the netns route generation](https://lore.kernel.org/all/cover.1795642432.git.dahern@nvidia.com/)&quot;">​</a></h3><p><em>David Ahern (<a href="mailto:dsahern@kernel.org" target="_blank" rel="noreferrer">dsahern@kernel.org</a>)｜netdev</em></p><p>本系列总览：IPv6 dst 通过 cookie 验证，cookie 由持有者（socket、dst_cache、xfrm bundle、IPVS 等）在存储 dst 时从路由节点的 fn_sernum 捕获，但查找与捕获之间落地的路由变更会被折叠进 cookie，使过期 dst 看似有效。只有 nexthop object 的 pcpu 路由携带自己的 generation，且失效的 pcpu dst 可被重新盖章而再次对所有持有者有效。结果是 dst 持续绕过路由变更，本系列以 netns 路由 generation 统一验证所有 dst。</p><blockquote><p><strong>学习价值</strong>：作为系列封面信，清晰梳理了 IPv6 dst 验证机制的历史缺陷与整体修复思路，是理解整个补丁系列的必读入口。</p></blockquote><h2 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h2><h3 id="d28fc1961291-·-patch-v2-1-2-xfs-factor-out-a-xfs-getfsmap-del-cursors-helper" tabindex="-1"><code>d28fc1961291</code> · <a href="https://lore.kernel.org/all/20261126013009.533557-2-zhangshida2026@163.com/" target="_blank" rel="noreferrer">[PATCH v2 1/2] xfs: factor out a xfs_getfsmap_del_cursors helper</a> <a class="header-anchor" href="#d28fc1961291-·-patch-v2-1-2-xfs-factor-out-a-xfs-getfsmap-del-cursors-helper" aria-label="Permalink to &quot;`d28fc1961291` · [[PATCH v2 1/2] xfs: factor out a xfs_getfsmap_del_cursors helper](https://lore.kernel.org/all/20261126013009.533557-2-zhangshida2026@163.com/)&quot;">​</a></h3><p><em>zhangshida2026 (<a href="mailto:zhangshida2026@163.com" target="_blank" rel="noreferrer">zhangshida2026@163.com</a>)｜lkml</em></p><p>该补丁将 XFS 中 data 和 rt device 的 getfsmap 遍历器在 group 边界和遍历结束时重复的 rmap btree cursor 删除逻辑抽取为 xfs_getfsmap_del_cursors 辅助函数。这是为后续在整个遍历过程中缓存 refcount cursor 做的准备工作，本身不引入功能变化。</p><blockquote><p><strong>学习价值</strong>：展示了内核开发中典型的重构手法：先提取公共代码再叠加优化，便于学习者理解补丁系列的分层结构。</p></blockquote><h3 id="d17b903f3cc3-·-patch-v2-2-2-xfs-optimize-getfsmap-by-reusing-and-advancing-the-refcount-cursor" tabindex="-1"><code>d17b903f3cc3</code> · <a href="https://lore.kernel.org/all/20261126013009.533557-3-zhangshida2026@163.com/" target="_blank" rel="noreferrer">[PATCH v2 2/2] xfs: optimize getfsmap by reusing and advancing the refcount cursor</a> <a class="header-anchor" href="#d17b903f3cc3-·-patch-v2-2-2-xfs-optimize-getfsmap-by-reusing-and-advancing-the-refcount-cursor" aria-label="Permalink to &quot;`d17b903f3cc3` · [[PATCH v2 2/2] xfs: optimize getfsmap by reusing and advancing the refcount cursor](https://lore.kernel.org/all/20261126013009.533557-3-zhangshida2026@163.com/)&quot;">​</a></h3><p><em>zhangshida2026 (<a href="mailto:zhangshida2026@163.com" target="_blank" rel="noreferrer">zhangshida2026@163.com</a>)｜lkml</em></p><p>该补丁优化 XFS 的 GETFSMAP 实现：原先 xfs_getfsmap_is_shared() 对每条 rmap 记录都要分配 refcount cursor 并从根节点搜索 refcount btree，开销很大。现在将 refcount cursor 保存在 xfs_getfsmap_info 中贯穿整个 group 遍历，用 xfs_refcount_lookup_le() 定位一次并缓存记录，随后用 xfs_btree_increment() 递增推进。</p><blockquote><p><strong>学习价值</strong>：很好的 btree cursor 复用优化案例，说明如何利用访问的局部性避免重复的 root-to-leaf 搜索。</p></blockquote><h3 id="_2f19b77dc144-·-patch-v2-0-2-xfs-optimize-getfsmap-by-reusing-and-advancing-the-refcount-cursor" tabindex="-1"><code>2f19b77dc144</code> · <a href="https://lore.kernel.org/all/20261126013009.533557-1-zhangshida2026@163.com/" target="_blank" rel="noreferrer">[PATCH v2 0/2] xfs: optimize getfsmap by reusing and advancing the refcount cursor</a> <a class="header-anchor" href="#_2f19b77dc144-·-patch-v2-0-2-xfs-optimize-getfsmap-by-reusing-and-advancing-the-refcount-cursor" aria-label="Permalink to &quot;`2f19b77dc144` · [[PATCH v2 0/2] xfs: optimize getfsmap by reusing and advancing the refcount cursor](https://lore.kernel.org/all/20261126013009.533557-1-zhangshida2026@163.com/)&quot;">​</a></h3><p><em>zhangshida2026 (<a href="mailto:zhangshida2026@163.com" target="_blank" rel="noreferrer">zhangshida2026@163.com</a>)｜lkml</em></p><p>本系列补丁（共 2 个）优化 XFS 的 GETFSMAP：原先每条 rmap 记录都要付出 cursor 分配/释放和一次从根到叶的 refcount btree 搜索成本，而实际上下一次查询几乎总是相邻的下一条 refcount 记录。系列改为每个 group 维护一个 refcount cursor，定位一次后随 rmap 遍历用 xfs_btree_increment() 前进，实测有明显性能提升。</p><blockquote><p><strong>学习价值</strong>：作为 cover letter 清楚展示了问题分析、方案设计和实测验证的完整流程，是学习提交高质量补丁系列的范例。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_9c78c47ae7da-·-patch-11-13-drm-tyr-return-usize-from-get-pgsize" tabindex="-1"><code>9c78c47ae7da</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-11-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 11/13] drm/tyr: return usize from get_pgsize()</a> <a class="header-anchor" href="#_9c78c47ae7da-·-patch-11-13-drm-tyr-return-usize-from-get-pgsize" aria-label="Permalink to &quot;`9c78c47ae7da` · [[PATCH 11/13] drm/tyr: return usize from get_pgsize()](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-11-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>Rust 的 <code>as</code> 转换会静默丢弃超出目标类型的位，且转换处看不出是否可能发生截断。作为减少 Tyr 驱动中 <code>as</code> 转换的一部分，本补丁让 get_pgsize() 以 <code>usize</code>（map_pages() 和 unmap_pages() 所需的类型）返回页大小和页数；页数仍由 <code>u64</code> 计算得出，因此转换移入 get_pgsize() 并附带说明其边界的 <code>// CAST:</code> 注释。无功能变更。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 内核驱动中类型安全转换的实践：优先让函数返回正确类型而非在调用点强转。</p></blockquote><h3 id="de57781664f3-·-patch-12-13-drm-tyr-justify-the-physical-address-cast-in-pt-map" tabindex="-1"><code>de57781664f3</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-12-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 12/13] drm/tyr: justify the physical address cast in pt_map()</a> <a class="header-anchor" href="#de57781664f3-·-patch-12-13-drm-tyr-justify-the-physical-address-cast-in-pt-map" aria-label="Permalink to &quot;`de57781664f3` · [[PATCH 12/13] drm/tyr: justify the physical address cast in pt_map()](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-12-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>本补丁为 pt_map() 中 DMA 地址到 PhysAddr 的转换补充理由：该转换保留，但附带 <code>// CAST:</code> 注释说明其安全性依据，并加上 <code>#[expect(clippy::as_conversions)]</code> 标记。这是 Tyr 驱动减少并规范化 <code>as</code> 转换系列的一部分，无功能变更。</p><blockquote><p><strong>学习价值</strong>：演示了当 <code>as</code> 转换不可避免时如何用注释和 lint 期望属性显式记录其合理性，是 Rust 内核代码审查规范的好例子。</p></blockquote><h3 id="_32d69183bea7-·-patch-13-13-drm-tyr-deny-clippy-as-conversions" tabindex="-1"><code>32d69183bea7</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-13-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 13/13] drm/tyr: deny <code>clippy::as_conversions</code></a> <a class="header-anchor" href="#_32d69183bea7-·-patch-13-13-drm-tyr-deny-clippy-as-conversions" aria-label="Permalink to &quot;`32d69183bea7` · [[PATCH 13/13] drm/tyr: deny `clippy::as_conversions`](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-13-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>本补丁在 Tyr 驱动中 deny <code>clippy::as_conversions</code>，使 Clippy 拒绝新增的 <code>as</code> 转换，除非带有 <code>#[expect]</code> 标记。驱动中保留的转换全部在 <code>// CAST:</code> 注释中说明理由并以此方式标记，从机制上防止了未来引入无说明的静默截断转换。</p><blockquote><p><strong>学习价值</strong>：展示了如何用 Clippy lint 策略在驱动层面强制执行类型转换规范，对 Rust 内核子系统的代码质量管控有参考价值。</p></blockquote><h3 id="_1f87372f58a3-·-patch-10-13-drm-tyr-add-split-u64-for-the-64-bit-register-values" tabindex="-1"><code>1f87372f58a3</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-10-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 10/13] drm/tyr: add split_u64() for the 64-bit register values</a> <a class="header-anchor" href="#_1f87372f58a3-·-patch-10-13-drm-tyr-add-split-u64-for-the-64-bit-register-values" aria-label="Permalink to &quot;`1f87372f58a3` · [[PATCH 10/13] drm/tyr: add split_u64() for the 64-bit register values](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-10-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>drm/tyr 驱动系列补丁之一，为减少 <code>as</code> 强制转换的数量，新增 <code>split_u64()</code> 作为 <code>join_u64()</code> 的对应函数，用于 MMU 代码中将 64 位寄存器值拆分为两个 32 位寄存器写入。原先分散在十处的转换现在集中到一处，每处都带有 <code>// CAST:</code> 注释。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：展示了如何在 Rust 内核驱动中通过封装辅助函数来集中管理不可避免的类型转换，是学习 Rust 安全类型实践的好例子。</p></blockquote><h3 id="f752cc4c7f55-·-patch-09-13-drm-tyr-justify-the-casts-of-enums-to-their-integer-value" tabindex="-1"><code>f752cc4c7f55</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-9-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 09/13] drm/tyr: justify the casts of enums to their integer value</a> <a class="header-anchor" href="#f752cc4c7f55-·-patch-09-13-drm-tyr-justify-the-casts-of-enums-to-their-integer-value" aria-label="Permalink to &quot;`f752cc4c7f55` · [[PATCH 09/13] drm/tyr: justify the casts of enums to their integer value](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-9-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁为 drm/tyr 驱动中将 enum 转换为其整数值的 <code>as</code> 转换添加说明性注释。由于 <code>as</code> 是 Rust 读取 enum 值的方式，这些转换被保留，但每处都添加了 <code>// CAST:</code> 注释和 <code>#[expect(clippy::as_conversions)]</code>，以便能为该驱动启用 clippy 的 as_conversions lint。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：说明了在无法消除 <code>as</code> 转换时如何用 lint 例外和注释保持代码可审计性，对理解 Rust 内核代码质量规范很有帮助。</p></blockquote><h3 id="c52fb0d3d8f6-·-patch-08-13-drm-tyr-use-vmmapflags-all-bits-to-validate-map-flags" tabindex="-1"><code>c52fb0d3d8f6</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-8-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 08/13] drm/tyr: use VmMapFlags::all_bits() to validate map flags</a> <a class="header-anchor" href="#c52fb0d3d8f6-·-patch-08-13-drm-tyr-use-vmmapflags-all-bits-to-validate-map-flags" aria-label="Permalink to &quot;`c52fb0d3d8f6` · [[PATCH 08/13] drm/tyr: use VmMapFlags::all_bits() to validate map flags](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-8-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁在 drm/tyr 驱动的 <code>VmMapFlags::try_from()</code> 中，不再将每个 <code>VmFlag</code> 变体转换为 <code>u32</code> 来构建有效标志掩码，而是直接使用 <code>impl_flags!</code> 宏已生成的 <code>all_bits()</code> 方法。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：演示了利用宏生成的元数据（如 all_bits()）消除手动位掩码构造的技巧，是 Rust 驱动中减少冗余转换的实用案例。</p></blockquote><h3 id="_3de2be884de3-·-patch-07-13-drm-tyr-use-cv-for-constant-conversions" tabindex="-1"><code>3de2be884de3</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-7-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 07/13] drm/tyr: use <code>cv!</code> for constant conversions</a> <a class="header-anchor" href="#_3de2be884de3-·-patch-07-13-drm-tyr-use-cv-for-constant-conversions" aria-label="Permalink to &quot;`3de2be884de3` · [[PATCH 07/13] drm/tyr: use `cv!` for constant conversions](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-7-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 drm/tyr 驱动中的常量转换改用 <code>cv!</code> 宏，该宏在值超出目标类型范围时会导致编译失败，从而避免 <code>as</code> 转换静默截断的风险。涉及 file.rs、regs.rs 和 vm.rs 三个文件。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：介绍了 <code>cv!</code> 宏这种编译期安全的常量转换方案，体现了 Rust 内核社区对消除静默数据截断的工程实践。</p></blockquote><h3 id="_8b7575555046-·-patch-05-13-drm-tyr-use-sizeconstants-for-the-u32-and-u64-size-constants" tabindex="-1"><code>8b7575555046</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-5-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 05/13] drm/tyr: use SizeConstants for the u32 and u64 size constants</a> <a class="header-anchor" href="#_8b7575555046-·-patch-05-13-drm-tyr-use-sizeconstants-for-the-u32-and-u64-size-constants" aria-label="Permalink to &quot;`8b7575555046` · [[PATCH 05/13] drm/tyr: use SizeConstants for the u32 and u64 size constants](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-5-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁在 drm/tyr 驱动中使用 <code>SizeConstants</code> trait 提供的 u32 和 u64 版本的尺寸常量（如 <code>u64::SZ_4K</code>），替代 <code>usize</code> 类型的 <code>SZ_*</code> 常量加 <code>as</code> 转换的写法，使混合整数类型的表达式无需任何一侧进行强制转换。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：展示了通过提供多类型常量定义来从根源上消除 <code>as</code> 转换的设计思路，对编写类型安全的 Rust 内核代码有参考价值。</p></blockquote><h3 id="f1d98260d93f-·-patch-06-13-drm-tyr-replace-lossless-as-casts-with-from-and-fromsafecast" tabindex="-1"><code>f1d98260d93f</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-6-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 06/13] drm/tyr: replace lossless <code>as</code> casts with From and FromSafeCast</a> <a class="header-anchor" href="#f1d98260d93f-·-patch-06-13-drm-tyr-replace-lossless-as-casts-with-from-and-fromsafecast" aria-label="Permalink to &quot;`f1d98260d93f` · [[PATCH 06/13] drm/tyr: replace lossless `as` casts with From and FromSafeCast](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-6-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 drm/tyr 驱动中无损的 <code>as</code> 转换替换为 <code>FromSafeCast</code> 和 <code>From</code> 实现，例如 <code>usize</code> 到 <code>u64</code>、<code>u32</code> 到 <code>usize</code> 以及 <code>Bounded&lt;u64, 8&gt;</code> 到 <code>u8</code> 的转换。<code>FromSafeCast</code> 仅在所有架构上都不丢失位的转换中实现，保证转换安全性。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：讲解了 <code>FromSafeCast</code> trait 如何在类型系统层面保证转换无损，是理解 Rust 内核抽象层类型安全设计的优秀素材。</p></blockquote><h3 id="fd76f69596d8-·-patch-04-13-drm-tyr-convert-entryheader-to-bitfield" tabindex="-1"><code>fd76f69596d8</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-4-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 04/13] drm/tyr: convert EntryHeader to <code>bitfield!</code></a> <a class="header-anchor" href="#fd76f69596d8-·-patch-04-13-drm-tyr-convert-entryheader-to-bitfield" aria-label="Permalink to &quot;`fd76f69596d8` · [[PATCH 04/13] drm/tyr: convert EntryHeader to `bitfield!`](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-4-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 drm/tyr 驱动中解析固件条目的 <code>EntryHeader</code> 从手写掩码和移位改为使用 <code>bitfield!</code> 宏。原先条目类型经 <code>as</code> 截断为 <code>u8</code>，大小以 <code>u32</code> 返回后再被转换为 <code>usize</code>；改用 <code>bitfield!</code> 后字段成为携带位宽信息的 <code>Bounded</code> 值。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：演示了 <code>bitfield!</code> 宏在硬件寄存器解析中的应用，相比手写位操作能提供更强的类型安全保障。</p></blockquote><h3 id="fddef1ca45ff-·-patch-03-13-drm-tyr-convert-the-lock-region-exponents-from-u8-to-u32" tabindex="-1"><code>fddef1ca45ff</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-3-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 03/13] drm/tyr: convert the lock region exponents from u8 to u32</a> <a class="header-anchor" href="#fddef1ca45ff-·-patch-03-13-drm-tyr-convert-the-lock-region-exponents-from-u8-to-u32" aria-label="Permalink to &quot;`fddef1ca45ff` · [[PATCH 03/13] drm/tyr: convert the lock region exponents from u8 to u32](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-3-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 drm/tyr 驱动 <code>as_start_update()</code> 中的锁区域指数从 <code>u8</code> 改为 <code>u32</code>。该函数通过 <code>trailing_zeros()</code> 和 <code>leading_zeros()</code>（返回 <code>u32</code>）计算需要锁定区域的大小的二次幂指数，原先用 <code>as</code> 缩窄为 <code>u8</code>，之后又为 <code>checked_shl()</code> 扩宽回 <code>u32</code>。保持 <code>u32</code> 类型消除了这些转换。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：说明了选择正确的中间类型可以自然消除不必要的缩窄和扩宽转换，是类型驱动重构的典型案例。</p></blockquote><h3 id="_054a9f433f1f-·-patch-01-13-drm-tyr-convert-seatinfo-slot-from-u8-to-usize" tabindex="-1"><code>054a9f433f1f</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-1-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 01/13] drm/tyr: convert SeatInfo::slot from u8 to usize</a> <a class="header-anchor" href="#_054a9f433f1f-·-patch-01-13-drm-tyr-convert-seatinfo-slot-from-u8-to-usize" aria-label="Permalink to &quot;`054a9f433f1f` · [[PATCH 01/13] drm/tyr: convert SeatInfo::slot from u8 to usize](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-1-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 drm/tyr 驱动中 <code>SeatInfo::slot</code> 从 <code>u8</code> 改为 <code>usize</code>。槽位索引原先存储为 <code>u8</code>，而使用它的代码需要 <code>usize</code>，导致进出各需一次 <code>as</code> 转换，且 <code>SlotManager::new()</code> 还需限制不超过 256 个槽位以防止截断。改为 <code>usize</code> 后消除了转换和该人为限制。</p><blockquote><p><strong>学习价值</strong>：展示了字段类型选择不当如何引发连锁的转换和人为限制，以及按使用场景选择存储类型的重构原则。</p></blockquote><h3 id="_077d148c8ec6-·-patch-02-13-drm-tyr-convert-vmasdata-va-bits-from-u8-to-u32" tabindex="-1"><code>077d148c8ec6</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-2-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 02/13] drm/tyr: convert VmAsData::va_bits from u8 to u32</a> <a class="header-anchor" href="#_077d148c8ec6-·-patch-02-13-drm-tyr-convert-vmasdata-va-bits-from-u8-to-u32" aria-label="Permalink to &quot;`077d148c8ec6` · [[PATCH 02/13] drm/tyr: convert VmAsData::va_bits from u8 to u32](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-2-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>该补丁将 drm/tyr 驱动中 <code>VmAsData::va_bits</code> 从 <code>u8</code> 改为 <code>u32</code>。<code>VmAsData::new()</code> 接收的虚拟地址位数是 <code>u32</code>，原先用 <code>as</code> 缩窄存入 <code>u8</code> 字段，而唯一读取该字段的 <code>as_config()</code> 又将其扩宽为 <code>u64</code>。改为 <code>u32</code> 存储后消除了转换。无功能性变更。</p><blockquote><p><strong>学习价值</strong>：与系列其他补丁一致，体现了根据数据流上下游类型统一字段类型以消除 <code>as</code> 转换的系统性重构方法。</p></blockquote><h3 id="b99b02811a56-·-patch-00-13-drm-tyr-reduce-the-number-of-as-casts" tabindex="-1"><code>b99b02811a56</code> · <a href="https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-0-2b2f53164d86@collabora.com/" target="_blank" rel="noreferrer">[PATCH 00/13] drm/tyr: reduce the number of <code>as</code> casts</a> <a class="header-anchor" href="#b99b02811a56-·-patch-00-13-drm-tyr-reduce-the-number-of-as-casts" aria-label="Permalink to &quot;`b99b02811a56` · [[PATCH 00/13] drm/tyr: reduce the number of `as` casts](https://lore.kernel.org/all/20261125-b4-tyr-as-casts-v1-0-2b2f53164d86@collabora.com/)&quot;">​</a></h3><p><em>Daniel Almeida (<a href="mailto:daniel.almeida@collabora.com" target="_blank" rel="noreferrer">daniel.almeida@collabora.com</a>)｜rust-for-linux</em></p><p>本系列补丁针对 Rust 编写的 DRM GPU 驱动 tyr，减少 <code>as</code> 类型转换的数量。<code>as</code> 转换会静默丢弃超出目标类型的位，存在安全隐患，Tyr 中共有 86 处此类转换，本系列移除了 62 处。补丁通过改变值的存储类型、利用内核已有的 <code>SizeConstants</code>、<code>From</code>、<code>FromSafeCast</code>、<code>cv!</code> 和 <code>impl_flags!</code> 的 <code>all_bits()</code> 等设施来消除转换，剩余 24 处转换均以 <code>// CAST:</code> 注释说明理由并标记 <code>#[expect(clippy::as_conversions)]</code>。</p><blockquote><p><strong>学习价值</strong>：展示了如何在真实驱动中运用 Rust 类型系统和 clippy lint 消除不安全的 <code>as</code> 转换，是学习内核 Rust 编码规范的优秀实例。</p></blockquote><h3 id="_3d1d8eef2b83-·-patch-drm-tyr-clamp-va-bits-to-available-bits" tabindex="-1"><code>3d1d8eef2b83</code> · <a href="https://lore.kernel.org/all/20261125-b4-va_bits_clamp-v1-1-07e2bb33eb50@collabora.com/" target="_blank" rel="noreferrer">[PATCH] drm/tyr: clamp va_bits to available bits</a> <a class="header-anchor" href="#_3d1d8eef2b83-·-patch-drm-tyr-clamp-va-bits-to-available-bits" aria-label="Permalink to &quot;`3d1d8eef2b83` · [[PATCH] drm/tyr: clamp va_bits to available bits](https://lore.kernel.org/all/20261125-b4-va_bits_clamp-v1-1-07e2bb33eb50@collabora.com/)&quot;">​</a></h3><p><em>Deborah Brouwer (<a href="mailto:deborah.brouwer@collabora.com" target="_blank" rel="noreferrer">deborah.brouwer@collabora.com</a>)｜rust-for-linux</em></p><p>Tyr 驱动根据 GPU 报告的虚拟地址位数创建虚拟地址空间，但页表映射操作将输入虚拟地址宽度限制为 unsigned long。在 32 位系统上这可能导致创建超出系统支持的虚拟地址空间。补丁检查 GPU 支持的虚拟地址位数是否超过 unsigned long 宽度，若超过则将其 clamp 到较小值，与 panthor_mmu_init() 中已有的处理保持一致。</p><blockquote><p><strong>学习价值</strong>：说明了 GPU MMU 虚拟地址空间与 CPU 位宽的匹配问题，对理解驱动中的地址空间初始化和跨 32/64 位系统的兼容性处理很有帮助。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="e8d2f61b8f35-·-postgresql-19-delivering-nice-performance-gains-benchmarks-on-6th-gen-amd-epyc-venice" tabindex="-1"><code>e8d2f61b8f35</code> · <a href="https://www.phoronix.com/review/postgresql-19-benchmarks" target="_blank" rel="noreferrer">PostgreSQL 19 Delivering Nice Performance Gains, Benchmarks On 6th Gen AMD EPYC Venice</a> <a class="header-anchor" href="#e8d2f61b8f35-·-postgresql-19-delivering-nice-performance-gains-benchmarks-on-6th-gen-amd-epyc-venice" aria-label="Permalink to &quot;`e8d2f61b8f35` · [PostgreSQL 19 Delivering Nice Performance Gains, Benchmarks On 6th Gen AMD EPYC Venice](https://www.phoronix.com/review/postgresql-19-benchmarks)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>PostgreSQL 19.0 正式发布（因 AI/LLM 负担导致开源开发者资源紧张而延期），在 AMD 第六代 EPYC Venice 平台上的基准测试显示出相比 PostgreSQL 18 的显著性能提升。</p><blockquote><p><strong>学习价值</strong>：数据库性能基准测试，可了解 EPYC 新平台与 PostgreSQL 的性能表现，但与内核学习关联不大。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="_9c6528f9b667-·-next-20261125-linux-next" tabindex="-1"><code>9c6528f9b667</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261125-2026-11-25" target="_blank" rel="noreferrer">next-20261125: linux-next</a> <a class="header-anchor" href="#_9c6528f9b667-·-next-20261125-linux-next" aria-label="Permalink to &quot;`9c6528f9b667` · [next-20261125: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261125-2026-11-25)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026 年 11 月 25 日发布 next-20261125 版本。linux-next 是内核主线合并前的集成测试树，汇集各子系统分支的待合并补丁。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 版本有助于学习者了解即将进入主线的特性动态，但该条目本身仅是版本发布信息，无技术细节。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="_6e24007d38fd-·-dave-taht-given-the-jonathan-b-postel-service-award" tabindex="-1"><code>6e24007d38fd</code> · <a href="https://lwn.net/Articles/1109691/" target="_blank" rel="noreferrer">Dave Täht given the Jonathan B. Postel Service Award</a> <a class="header-anchor" href="#_6e24007d38fd-·-dave-taht-given-the-jonathan-b-postel-service-award" aria-label="Permalink to &quot;`6e24007d38fd` · [Dave Täht given the Jonathan B. Postel Service Award](https://lwn.net/Articles/1109691/)&quot;">​</a></h3><p><em>corbet｜lwn</em></p><p>Dave Täht 因长期致力于改善互联网而被 Internet Society 授予 Jonathan B. Postel Service Award。他最著名的贡献是发现并推动解决 bufferbloat 问题，其成果体现在无卡顿的视频通话中，他还曾帮助 Starlink 解决延迟挑战，并在尼加拉瓜等地扩展网络连接。他指导并影响了众多后继者继续对抗 bufferbloat。</p><blockquote><p><strong>学习价值</strong>：了解 bufferbloat 问题的历史背景及其对网络延迟优化的深远影响，对学习 Linux 网络栈（如 fq_codel/sch_cake）很有启发。</p></blockquote><h3 id="_9e7f1c2fcb60-·-tainting-or-not-on-manual-driver-binding-1" tabindex="-1"><code>9e7f1c2fcb60</code> · <a href="https://lwn.net/Articles/1103714/" target="_blank" rel="noreferrer">[$] Tainting (or not) on manual driver binding</a> <a class="header-anchor" href="#_9e7f1c2fcb60-·-tainting-or-not-on-manual-driver-binding-1" aria-label="Permalink to &quot;`9e7f1c2fcb60` · [[$] Tainting (or not) on manual driver binding](https://lwn.net/Articles/1103714/)&quot;">​</a></h3><p><em>corbet｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>Greg Kroah-Hartman 在 7.4 merge window 中合入了一个补丁，当用户空间手动 bind/unbind 设备驱动时将内核标记为 tainted，以抵御 fuzzer 产生的大量虚假 bug 报告。但该改动也阻碍了一些真实使用场景，经讨论后被 revert。这暴露了内核在驱动绑定接口设计上的不足。</p><blockquote><p><strong>学习价值</strong>：展示了内核 taint 机制的实际用途与副作用，以及社区如何权衡 fuzzing 噪音与合法用例，是理解内核开发流程的好案例。</p></blockquote><h3 id="_98b73f157158-·-pop-os-26-04-lts-released" tabindex="-1"><code>98b73f157158</code> · <a href="https://lwn.net/Articles/1109662/" target="_blank" rel="noreferrer">Pop!_OS 26.04 LTS released</a> <a class="header-anchor" href="#_98b73f157158-·-pop-os-26-04-lts-released" aria-label="Permalink to &quot;`98b73f157158` · [Pop!_OS 26.04 LTS released](https://lwn.net/Articles/1109662/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>System76 发布了基于 Ubuntu 26.04 LTS 的 Pop!_OS 26.04 LTS。主要新特性包括数位板支持、自动更新以及多款新的 COSMIC 应用。24.04 LTS 用户的升级通道将于 12 月开放。</p><blockquote><p><strong>学习价值</strong>：发行版发布新闻，对内核学习本身价值有限，仅可了解 COSMIC 桌面（Rust 编写）生态的进展。</p></blockquote><h3 id="_7c31897b3205-·-security-updates-for-wednesday" tabindex="-1"><code>7c31897b3205</code> · <a href="https://lwn.net/Articles/1109650/" target="_blank" rel="noreferrer">Security updates for Wednesday</a> <a class="header-anchor" href="#_7c31897b3205-·-security-updates-for-wednesday" aria-label="Permalink to &quot;`7c31897b3205` · [Security updates for Wednesday](https://lwn.net/Articles/1109650/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>各发行版发布例行安全更新，涉及 AlmaLinux、Debian、Fedora、Mageia、Oracle 等多个发行版的众多软件包，包括 openssh、chromium、runc、flatpak 等组件的安全修复。</p><blockquote><p><strong>学习价值</strong>：常规安全更新汇总，可作为跟踪发行版安全维护节奏的参考，对内核学习直接价值较低。</p></blockquote><h3 id="_4baed94943b4-·-kosmickrisp-now-the-go-to-solution-for-vulkan-on-macs-in-place-of-moltenvk" tabindex="-1"><code>4baed94943b4</code> · <a href="https://www.phoronix.com/news/Vulkan-Macs-Go-KosmicKrisp" target="_blank" rel="noreferrer">KosmicKrisp Now The Go-To Solution For Vulkan On Macs In Place Of MoltenVK</a> <a class="header-anchor" href="#_4baed94943b4-·-kosmickrisp-now-the-go-to-solution-for-vulkan-on-macs-in-place-of-moltenvk" aria-label="Permalink to &quot;`4baed94943b4` · [KosmicKrisp Now The Go-To Solution For Vulkan On Macs In Place Of MoltenVK](https://www.phoronix.com/news/Vulkan-Macs-Go-KosmicKrisp)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>LunarG 主导的 KosmicKrisp 项目现已成为现代 Apple 设备上 Vulkan API 支持的首选方案，取代了原先在 macOS/iOS 上将 Vulkan 叠加于 Metal 之上的 MoltenVK。</p><blockquote><p><strong>学习价值</strong>：图形驱动生态新闻，与 Linux 内核学习关联较弱，仅涉及 Vulkan/Mesa 生态背景知识。</p></blockquote><h3 id="_5cb48f1587f5-·-pop-os-26-04-lts-vs-pop-os-24-04-lts-benchmarks" tabindex="-1"><code>5cb48f1587f5</code> · <a href="https://www.phoronix.com/review/pop-os-2604-benchmarks" target="_blank" rel="noreferrer">Pop!_OS 26.04 LTS vs. Pop!_OS 24.04 LTS Benchmarks</a> <a class="header-anchor" href="#_5cb48f1587f5-·-pop-os-26-04-lts-vs-pop-os-24-04-lts-benchmarks" aria-label="Permalink to &quot;`5cb48f1587f5` · [Pop!_OS 26.04 LTS vs. Pop!_OS 24.04 LTS Benchmarks](https://www.phoronix.com/review/pop-os-2604-benchmarks)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>System76 发布 Pop!_OS 26.04 LTS 后，Phoronix 将其与 24.04 LTS 进行了性能对比测试，测试基于新发货的 System76 Thelio Prime SFF 主机。</p><blockquote><p><strong>学习价值</strong>：发行版性能对比基准，对内核学习直接价值有限。</p></blockquote><h3 id="_8adff4bb47e8-·-servo-now-supports-html-video-captions-flutter-web-content-working" tabindex="-1"><code>8adff4bb47e8</code> · <a href="https://www.phoronix.com/news/Servo-0.8-October-2026" target="_blank" rel="noreferrer">Servo Now Supports HTML Video Captions, Flutter Web Content Working</a> <a class="header-anchor" href="#_8adff4bb47e8-·-servo-now-supports-html-video-captions-flutter-web-content-working" aria-label="Permalink to &quot;`8adff4bb47e8` · [Servo Now Supports HTML Video Captions, Flutter Web Content Working](https://www.phoronix.com/news/Servo-0.8-October-2026)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>基于 Rust 的开源浏览器引擎 Servo 发布 0.8 版本，十月新增了 HTML 视频字幕支持，Flutter Web 内容渲染也已可用，Servoshell 演示浏览器同步获得多项改进。</p><blockquote><p><strong>学习价值</strong>：展示了 Rust 在大型系统软件（浏览器引擎）中的实际应用，对关注 Rust 生态的内核学习者有一定参考意义。</p></blockquote><h3 id="_8a431b2d5e62-·-gnu-linux-libre-celebrates-reverse-engineered-firmware-for-old-802-11-b-g-wifi-chipset" tabindex="-1"><code>8a431b2d5e62</code> · <a href="https://www.phoronix.com/news/GNU-Linux-Libre-VIA-VT6656" target="_blank" rel="noreferrer">GNU Linux-Libre Celebrates Reverse Engineered Firmware For Old 802.11 b/g WiFi Chipset</a> <a class="header-anchor" href="#_8a431b2d5e62-·-gnu-linux-libre-celebrates-reverse-engineered-firmware-for-old-802-11-b-g-wifi-chipset" aria-label="Permalink to &quot;`8a431b2d5e62` · [GNU Linux-Libre Celebrates Reverse Engineered Firmware For Old 802.11 b/g WiFi Chipset](https://www.phoronix.com/news/GNU-Linux-Libre-VIA-VT6656)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>GNU Linux-libre 项目为 Linux 6.12 LTS 发布了少见的更新，庆祝一款老旧 802.11 b/g WiFi 芯片组通过逆向工程固件在其去除了专有固件的内核上可用，成为新认可的驱动选项。</p><blockquote><p><strong>学习价值</strong>：涉及 Linux-libre 的去 blob 化理念和逆向工程固件案例，可帮助理解内核固件加载机制与自由软件立场。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>4db90b673261</code> · <a href="https://lore.kernel.org/all/cover.1795642432.git.dahern@nvidia.com/" target="_blank" rel="noreferrer">[PATCH net-next v2 00/13] ipv6: validate cached dsts against the netns route generation</a></li><li><code>96e5a91f59fa</code> · <a href="https://lore.kernel.org/all/20261126014327.1638133-1-rjethwani@purestorage.com/" target="_blank" rel="noreferrer">[PATCH net v7 0/3] tls: fix device-down socket lifetime and offload state</a></li><li><code>3ceff5b43fc1</code> · <a href="https://lore.kernel.org/all/20261125233020.1380594-1-vitorhg20080@gmail.com/" target="_blank" rel="noreferrer">[PATCH RFC 00/19] riscv: Add initial support for Espressif ESP32-P4</a></li><li><code>aa7012012002</code> · <a href="https://lore.kernel.org/all/20261125-hugetlb_fixes_2-v1-21-db27fd2f71a8@kernel.org/" target="_blank" rel="noreferrer">[PATCH 21/21] RFC: mm/hugetlb_cgroup: charge faults to mm-&gt;owner</a></li></ul>',248)])])}const b=t(n,[["render",l]]);export{f as __pageData,b as default};
